const request = require('request');

const options = {
  method: 'PATCH',
  url: 'https://api.procore.com/rest/v1.0/submittal_approvers/%7Bid%7D',
  qs: {
    project_id: 'SOME_INTEGER_VALUE',
    send_emails: 'SOME_BOOLEAN_VALUE',
    submittal_id: 'SOME_INTEGER_VALUE'
  },
  headers: {'content-type': 'application/json'},
  body: {
    submittal_approver: {
      attachments_to_upload: ['string'],
      attachment_ids: [0],
      upload_ids: ['4120226e-36a8-416f-970e-880bae78164f', 'de07e35a-4860-4f96-acd8-8360833dc495'],
      comment: 'string',
      submittal_response_id: 0,
      sent_date: '2019-4-17',
      returned_date: '2019-4-17',
      forward_to: {user_id: 161072, due_date: '2019-09-20'},
      associated_attachments: [{attachment_id: 0, attachment_source_id: 0, attachment_source_type: 'string'}]
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Patch,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/submittal_approvers/%7Bid%7D?project_id=SOME_INTEGER_VALUE&send_emails=SOME_BOOLEAN_VALUE&submittal_id=SOME_INTEGER_VALUE"),
    Content = new StringContent("{\"submittal_approver\":{\"attachments_to_upload\":[\"string\"],\"attachment_ids\":[0],\"upload_ids\":[\"4120226e-36a8-416f-970e-880bae78164f\",\"de07e35a-4860-4f96-acd8-8360833dc495\"],\"comment\":\"string\",\"submittal_response_id\":0,\"sent_date\":\"2019-4-17\",\"returned_date\":\"2019-4-17\",\"forward_to\":{\"user_id\":161072,\"due_date\":\"2019-09-20\"},\"associated_attachments\":[{\"attachment_id\":0,\"attachment_source_id\":0,\"attachment_source_type\":\"string\"}]}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
